import React, { forwardRef } from 'react';
import type { Types } from '@fiverr-private/theme';
import { Container } from '@fiverr-private/layout_components';
import { Text } from '@fiverr-private/typography';
import { ChatMessage, ChatMessageAuthor } from '../utils';

interface MessageProps
  extends Pick<Types.ContainerProps, 'position' | 'top' | 'left' | 'width' | 'height' | 'transform'> {
  message: ChatMessage;
  currentAuthor: ChatMessageAuthor;
  ['data-index']?: number;
}

function SimpleMessageBase(
  { message, currentAuthor, position, top, left, width, height, transform, 'data-index': dataIndex }: MessageProps,
  ref: React.ForwardedRef<HTMLDivElement>
) {
  const isOwnMessage = message.author.userId === currentAuthor.userId;
  const displayName = message.author.username === 'agent' ? undefined : message.author.displayName;
  const messageLines = message.body.split('\n');

  return (
    <Container
      display="flex"
      justifyContent={isOwnMessage ? 'flexEnd' : 'flexStart'}
      position={position}
      top={top}
      left={left}
      width={width}
      height={height}
      transform={transform}
      data-index={dataIndex}
      ref={ref}
    >
      <Text
        size="b_sm"
        color="bodyPrimary"
        key={message.id}
        paddingY="0.5"
        maxWidth="80%"
        textAlign={isOwnMessage ? 'end' : 'start'}
      >
        <Text as="b" fontWeight="bold" color="bodyPrimary" whiteSpace="nowrap" size="b_sm">
          {isOwnMessage ? 'Me' : displayName}
        </Text>
        {': '}

        {messageLines.map((line, index) => (
          <React.Fragment key={index}>
            {line}
            {index < messageLines.length - 1 && <br />}
          </React.Fragment>
        ))}
      </Text>
    </Container>
  );
}

export default forwardRef(SimpleMessageBase);
