import React from 'react';
import { Container } from '@fiverr-private/layout_components';
import { renderChildren } from '@fiverr-private/ui_utils';
import { Fade } from '@fiverr-private/transition';
import type { Types } from '@fiverr-private/theme';
import { IDS } from '../constants';

interface ChatScrollToBottomSlotProps {
  /**
   * Whether the slot content is visible. Controlled by `ChatScrollArea` component if placed inside it.
   * @default false
   */
  visible?: boolean;
  /**
   * Callback to be called when the slot content is clicked. Controlled by `ChatScrollArea` component if placed inside it.
   */
  onClick?: (event: React.MouseEvent<HTMLDivElement>) => void;
  /**
   * Distance to slot content from the top edge of the `ChatScrollArea` component.
   */
  top?: Types.ContainerProps['top'];
  /**
   * Distance to slot content from the right edge of the `ChatScrollArea` component.
   */
  right?: Types.ContainerProps['right'];
  /**
   * Distance to slot content from the bottom edge of the `ChatScrollArea` component.
   */
  bottom?: Types.ContainerProps['bottom'];
  /**
   * Distance to slot content from the left edge of the `ChatScrollArea` component.
   */
  left?: Types.ContainerProps['left'];
  children: React.ReactNode;
}

function ChatScrollToBottomSlot({
  children,
  visible = false,
  onClick,
  top,
  right,
  bottom,
  left,
}: ChatScrollToBottomSlotProps) {
  return (
    <Fade unmountOnExit in={visible}>
      <Container position="absolute" bottom={bottom} right={right} top={top} left={left}>
        {renderChildren(children, { onClick })}
      </Container>
    </Fade>
  );
}

ChatScrollToBottomSlot.id = IDS.CHAT_SCROLL_TO_BOTTOM_SLOT;
ChatScrollToBottomSlot.displayName = 'ChatScrollToBottomSlot';

export default ChatScrollToBottomSlot;
