import React from 'react';
import { QueryClient, QueryClientProvider, useInfiniteQuery } from '@tanstack/react-query';
import { Center } from '@fiverr-private/layout_components';
import { Typography } from '@fiverr-private/typography';
import ChatScrollArea from '../..';
import SimpleMessage from './SimpleMessage';
import { useMockChat } from './hooks/useMockChat';

function WithSmallLoadingThreshold() {
  const chat = useMockChat({ numberOfAuthors: 2, numberOfMessages: 90 });
  const { data, fetchNextPage, hasNextPage, isFetchingNextPage } = useInfiniteQuery({
    queryKey: ['messages'],
    queryFn: ({ pageParam }) =>
      chat.fetchMessages({
        pageSize: 30,
        cursor: pageParam as string,
        timeout: 1000,
      }),
    getNextPageParam: (lastPage) => lastPage.cursor,
    select: (data) => ({
      pages: [...data.pages].reverse(),
      pageParams: [...data.pageParams].reverse(),
    }),
    initialData: () => {
      const initialMessages = chat.getInitialMessages(30);
      return {
        pages: [initialMessages],
        pageParams: [initialMessages.cursor],
      };
    },
    enabled: false,
  });

  const messages = data?.pages.flatMap((page) => page.data) ?? [];

  return (
    <ChatScrollArea onLoadMore={fetchNextPage} hasMore={hasNextPage} paddingRight="4" loadingThreshold={0.1}>
      <Center flexShrink={0} height="48px">
        <Typography as="span" color="grey_700" size="b_sm" fontWeight="bold" fontStyle="italic">
          {isFetchingNextPage && 'Loading messages...'}
          {!hasNextPage && messages.length > 0 && 'No more messages'}
        </Typography>
      </Center>
      {messages.map((message) => (
        <SimpleMessage key={message.id} message={message} currentAuthor={chat.authors[0]} />
      ))}
    </ChatScrollArea>
  );
}

const queryClient = new QueryClient();

export default function WithSmallLoadingThresholdWithQueryClient() {
  return (
    <QueryClientProvider client={queryClient}>
      <WithSmallLoadingThreshold />
    </QueryClientProvider>
  );
}

