import React, { useCallback, useMemo, useState, useRef } from 'react';
import { faker } from '@faker-js/faker';
import { Avatar } from '@fiverr-private/avatar';
import { ArrowDownIcon, ArrowUpIcon, EmojiSmileyIcon, AttachmentIcon, SparkSolidIcon } from '@fiverr-private/visuals';
import { IconButton } from '@fiverr-private/button';
import { Container, Stack } from '@fiverr-private/layout_components';
import { Text, Link } from '@fiverr-private/typography';
import { TextareaGroup, Textarea, TextareaSlot } from '@fiverr-private/forms';
import ChatScrollToBottomSlot from '../../../ChatScrollToBottomSlot';
import ChatScrollArea from '../..';
import { type ChatMessage, groupMessages } from '../utils';
import { useMockChat } from './hooks/useMockChat';

function AiAvatar() {
  return (
    <Avatar username="Neo" size="xs" showBorder={false}>
      <SparkSolidIcon size="sm" color="purple_700" />
    </Avatar>
  );
}

function AIMessageGroup({ messages }: { messages: ChatMessage[] }) {
  return (
    <Stack gap="2" paddingY="2">
      <AiAvatar />
      <Stack direction="column" gap="1">
        {messages.map((message) => (
          <Text key={message.id} size="b_sm" color="bodyPrimary">
            {message.body}
          </Text>
        ))}
      </Stack>
    </Stack>
  );
}

function UserMessageGroup({ messages }: { messages: ChatMessage[] }) {
  return (
    <Stack direction="column" gap="1" paddingY="2" alignItems="flexEnd" paddingLeft="12">
      {messages.map((message) => (
        <Container key={message.id} paddingY="2" paddingX="4" backgroundColor="grey_300" borderRadius="lg">
          <Text size="b_sm" color="bodyPrimary" wordBreak="breakAll">
            {message.body}
          </Text>
        </Container>
      ))}
    </Stack>
  );
}

function ChatTextarea({ onSend }: { onSend: (message: string) => void }) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const handleSend = useCallback(() => {
    if (textareaRef.current?.value) {
      const value = textareaRef.current.value;
      onSend(value);
      setTimeout(() => {
        if (textareaRef.current) {
          textareaRef.current.value = '';
        }
      }, 0);
    }
  }, [onSend]);

  return (
    <TextareaGroup ref={textareaRef}>
      <Textarea placeholder="Ask anything" />
      <TextareaSlot position="bottom">
        <Stack gap="2">
          <IconButton variant="ghost" aria-label="Emoji picker" size="sm" shape="circle">
            <EmojiSmileyIcon />
          </IconButton>
          <IconButton variant="ghost" aria-label="Attachment" size="sm" shape="circle">
            <AttachmentIcon />
          </IconButton>
          <IconButton variant="filled" intent="primary" aria-label="Send" size="sm" shape="circle" onClick={handleSend}>
            <ArrowUpIcon />
          </IconButton>
        </Stack>
      </TextareaSlot>
    </TextareaGroup>
  );
}

export default function AIConversationExample() {
  const chat = useMockChat({ withAgent: true, numberOfMessages: 100 });
  const [messages, setMessages] = useState(chat.messages);
  const groupedMessages = useMemo(
    () => groupMessages(messages, (message, prevMessage) => message.author.username === prevMessage?.author.username),
    [messages]
  );

  const sendMessage = useCallback(
    (message: string) => {
      if (message) {
        setMessages((messages) => [...messages, { id: faker.datatype.uuid(), body: message, author: chat.authors[0] }]);
      }
    },
    [setMessages, chat]
  );

  return (
    <Stack direction="column" height="80vh" maxWidth="400px" margin="auto" gap="0" backgroundColor="grey_100">
      <ChatScrollArea paddingX="6" paddingTop="4" paddingBottom="2" flexGrow="1">
        {groupedMessages.map((messages) => {
          const GroupComponent = messages[0].author.username === 'agent' ? AIMessageGroup : UserMessageGroup;
          return <GroupComponent key={messages[0].id} messages={messages} />;
        })}
        <ChatScrollToBottomSlot bottom="8px" right="24px">
          <IconButton aria-label="Scroll to bottom" size="sm" background="white" variant="outline">
            <ArrowDownIcon />
          </IconButton>
        </ChatScrollToBottomSlot>
      </ChatScrollArea>
      <Container marginX="6" marginBottom="6" marginTop="px">
        <ChatTextarea onSend={sendMessage} />
        <Stack width="max-content" marginX="auto" marginTop="3">
          <Text size="b_xs" color="bodySecondary">
            Powered by AI
          </Text>
          <Text size="b_xs" color="bodySecondary">
            &bull;
          </Text>
          <Link href="#" size="b_xs" color="grey_900">
            Share feedback
          </Link>
        </Stack>
      </Container>
    </Stack>
  );
}

