import React from 'react';
import { ArrowDownIcon } from '@fiverr-private/visuals';
import { IconButton } from '@fiverr-private/button';
import ChatScrollToBottomSlot from '../../../ChatScrollToBottomSlot';
import ChatScrollArea from '../..';
import { useMockChat } from './hooks/useMockChat';
import SimpleMessage from './SimpleMessage';

export default function WithScrollToBottom() {
  const chat = useMockChat({ numberOfAuthors: 10, numberOfMessages: 1000 });
  return (
    <ChatScrollArea paddingRight="4">
      {chat.messages.map((message) => (
        <SimpleMessage key={message.id} message={message} currentAuthor={chat.authors[0]} />
      ))}
      <ChatScrollToBottomSlot bottom="4px" right="16px">
        <IconButton aria-label="Scroll to bottom" size="sm" background="white" variant="outline">
          <ArrowDownIcon />
        </IconButton>
      </ChatScrollToBottomSlot>
    </ChatScrollArea>
  );
}

