import React, { useRef, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import { ArrowDownIcon } from '@fiverr-private/visuals';
import { IconButton } from '@fiverr-private/button';
import { Container } from '@fiverr-private/layout_components';
import ChatScrollToBottomSlot from '../../../ChatScrollToBottomSlot';
import ChatScrollArea from '../..';
import SimpleMessage from './SimpleMessage';
import { useNewMessages } from './hooks/useNewMessages';
import { useMockChat } from './hooks/useMockChat';

export default function WithVirtualizedList() {
  const chat = useMockChat({ numberOfAuthors: 3, numberOfMessages: 10000 });
  const [messages, setMessages] = useState(chat.messages);
  const parentRef = useRef<HTMLDivElement>(null);

  useNewMessages(chat, setMessages);

  const virtualizer = useVirtualizer({
    count: messages.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 30,
  });

  const virtualItems = virtualizer.getVirtualItems();

  return (
    <ChatScrollArea paddingRight="4" ref={parentRef}>
      <Container flexShrink={0} height={virtualizer.getTotalSize()} width="100%" position="relative">
        <Container
          position="absolute"
          top={0}
          left={0}
          width="100%"
          transform={`translateY(${virtualItems[0]?.start ?? 0}px)`}
        >
          {virtualItems.map((item) => (
            <SimpleMessage
              key={item.index}
              data-index={item.index}
              ref={virtualizer.measureElement}
              message={messages[item.index]}
              currentAuthor={chat.authors[0]}
            />
          ))}
        </Container>
      </Container>

      <ChatScrollToBottomSlot bottom="4px" right="16px">
        <IconButton aria-label="Scroll to bottom" size="sm" background="white" variant="outline">
          <ArrowDownIcon />
        </IconButton>
      </ChatScrollToBottomSlot>
    </ChatScrollArea>
  );
}

