import React, { forwardRef, useRef, useImperativeHandle } from 'react';
import { Container, Stack } from '@fiverr-private/layout_components';
import type { Types } from '@fiverr-private/theme';
import { findChildByType, renderChildren } from '@fiverr-private/ui_utils';
import { IDS } from '../constants';
import { useChatScrolling } from './hooks/useChatScrolling';

interface ChatScrollAreaProps
  extends Pick<
    Types.ContainerProps,
    | 'height'
    | 'minHeight'
    | 'maxHeight'
    | 'flexGrow'
    | 'padding'
    | 'paddingY'
    | 'paddingX'
    | 'paddingBottom'
    | 'paddingTop'
    | 'paddingLeft'
    | 'paddingRight'
  > {
  /**
   * Callback to load more messages when the user scrolls near the top of the container.
   */
  onLoadMore?: () => Promise<any>;
  /**
   * Whether there are more messages to load.
   * @default false
   */
  hasMore?: boolean;
  /**
   * The threshold for the user to be considered near the top of the scroll area. 1 unit equals 1 `offsetHeight` of the scroll area.
   * @default 3
   */
  loadingThreshold?: number;
  children: React.ReactNode;
}

function ChatScrollAreaBase(
  {
    onLoadMore,
    hasMore = false,
    loadingThreshold = 3,
    children,
    height = '300px',
    minHeight = '0px',
    maxHeight,
    flexGrow,
    padding,
    paddingY,
    paddingX,
    paddingBottom,
    paddingTop,
    paddingLeft,
    paddingRight,
  }: ChatScrollAreaProps,
  ref: React.ForwardedRef<HTMLDivElement>
) {
  const containerRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => containerRef.current as HTMLDivElement);

  const { isCloseToBottom, scrollToBottom } = useChatScrolling(containerRef, {
    hasMore,
    loadingThreshold,
    onLoadMore,
  });

  const scrollToBottomSlot = findChildByType(children, IDS.CHAT_SCROLL_TO_BOTTOM_SLOT);

  return (
    <Container position="relative" height={height} minHeight={minHeight} maxHeight={maxHeight} flexGrow={flexGrow}>
      <Stack
        ref={containerRef}
        direction="column"
        overflowY="scroll"
        height="100%"
        gap="0"
        padding={padding}
        paddingY={paddingY}
        paddingX={paddingX}
        paddingBottom={paddingBottom}
        paddingTop={paddingTop}
        paddingLeft={paddingLeft}
        paddingRight={paddingRight}
      >
        <Container flexGrow="1" />
        {children}
      </Stack>
      {renderChildren(scrollToBottomSlot, {
        visible: !isCloseToBottom,
        onClick: scrollToBottom,
      })}
    </Container>
  );
}

const ChatScrollArea = forwardRef(ChatScrollAreaBase);

ChatScrollArea.displayName = 'ChatScrollArea';

export default ChatScrollArea;
