import React, { useEffect } from 'react';
import random from 'lodash/random';
import { faker } from '@faker-js/faker';
import { QueryClient, QueryClientProvider, useInfiniteQuery, useQueryClient } from '@tanstack/react-query';
import { Center } from '@fiverr-private/layout_components';
import { Typography } from '@fiverr-private/typography';
import ChatScrollArea from '../..';
import { useMockChat } from './hooks/useMockChat';
import SimpleMessage from './SimpleMessage';

function WithPaginatedMessages() {
  const chat = useMockChat({ numberOfAuthors: 2, numberOfMessages: 500 });
  const queryClient = useQueryClient();
  const { data, fetchNextPage, hasNextPage, isFetchingNextPage } = useInfiniteQuery({
    queryKey: ['messages'],
    queryFn: ({ pageParam }) =>
      chat.fetchMessages({
        pageSize: 100,
        cursor: pageParam as string,
        timeout: 100,
      }),
    getNextPageParam: (lastPage) => lastPage.cursor,
    select: (data) => ({
      pages: [...data.pages].reverse(),
      pageParams: [...data.pageParams].reverse(),
    }),
    initialData: () => {
      const initialMessages = chat.getInitialMessages(200);
      return {
        pages: [initialMessages],
        pageParams: [initialMessages.cursor],
      };
    },
    enabled: false,
  });

  useEffect(() => {
    const interval = setInterval(() => {
      queryClient.setQueryData(['messages'], (data: any) => {
        if (!data) {
          return;
        }
        const firstPage = data.pages[0];
        const updatedFirstPage = {
          ...firstPage,
          data: [
            ...firstPage.data,
            {
              id: faker.datatype.uuid(),
              body: faker.lorem.sentence(Math.floor(Math.random() * 20) + 3),
              author: chat.authors[random(0, chat.authors.length - 1)],
            },
          ],
        };
        return {
          pages: [updatedFirstPage, ...data.pages.slice(1)],
          pageParams: data.pageParams,
        };
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [queryClient, chat]);

  const messages = data?.pages.flatMap((page) => page.data) ?? [];

  return (
    <ChatScrollArea onLoadMore={fetchNextPage} hasMore={hasNextPage} paddingRight="4">
      <Center flexShrink={0} height="48px">
        <Typography as="span" color="grey_700" size="b_sm" fontWeight="bold" fontStyle="italic">
          {isFetchingNextPage && 'Loading messages...'}
          {!hasNextPage && messages.length > 0 && 'No more messages'}
        </Typography>
      </Center>
      {messages.map((message) => (
        <SimpleMessage key={message.id} message={message} currentAuthor={chat.authors[0]} />
      ))}
    </ChatScrollArea>
  );
}

const queryClient = new QueryClient();

export default function WithPaginatedMessagesWithQueryClient() {
  return (
    <QueryClientProvider client={queryClient}>
      <WithPaginatedMessages />
    </QueryClientProvider>
  );
}

