import { faker } from '@faker-js/faker';

export interface ChatMessageAuthor {
    userId: number;
    username: string;
    displayName?: string;
    profileImage?: string;
}

export interface ChatMessage {
    id: string;
    body: string;
    author: ChatMessageAuthor;
}

const waitFor = (timeout: number) => new Promise((resolve) => setTimeout(resolve, timeout));

const generateMockUserAuthors = (numberOfAuthors: number): ChatMessageAuthor[] =>
    Array.from({ length: numberOfAuthors }, (_, i) => ({
        userId: i + 1,
        username: faker.internet.userName(),
        displayName: faker.name.findName(),
        profileImage: faker.image.avatar(),
    }));

const generateMockAgentAuthor = (): ChatMessageAuthor => ({
    userId: 666,
    username: 'agent',
    displayName: 'Agent',
});

const generateMockMessages = (numberOfMessages: number, authors: ChatMessageAuthor[]): ChatMessage[] =>
    Array.from({ length: numberOfMessages }, () => {
        const author = authors[Math.floor(Math.random() * authors.length)];
        return {
            id: faker.datatype.uuid(),
            body: faker.lorem.sentence(Math.floor(Math.random() * 20) + 3),
            author,
        };
    }).reverse();

type MockChatProviderEvent = 'new-message' | 'someone-typing';
interface MockChatProviderEventPayload {
    'new-message': {
        message: ChatMessage;
    };
    'someone-typing': {
        userId: number;
    };
}

interface MockChatProviderProps {
    numberOfAuthors?: number;
    withAgent?: boolean;
    numberOfMessages: number;
}

interface FetchMessagesOptions {
    pageSize: number;
    cursor: string;
    timeout?: number;
}

export class MockChatProvider {
    messages: ChatMessage[];
    authors: ChatMessageAuthor[];
    private eventListeners: Record<MockChatProviderEvent, Set<(payload: any) => void>> = {
        'new-message': new Set(),
        'someone-typing': new Set(),
    };

    constructor({ numberOfAuthors, numberOfMessages, withAgent }: MockChatProviderProps) {
        if (withAgent) {
            this.authors = [...generateMockUserAuthors(1), generateMockAgentAuthor()];
        } else if (numberOfAuthors) {
            this.authors = generateMockUserAuthors(numberOfAuthors);
        }
        this.messages = generateMockMessages(numberOfMessages, this.authors);
    }

    getInitialMessages(pageSize: number) {
        const messagesPage = this.messages.slice(-pageSize);
        const hasMore = messagesPage[0] !== this.messages[0];
        return {
            data: messagesPage,
            cursor: hasMore ? messagesPage[0].id : null,
        };
    }

    async fetchMessages({ pageSize, cursor, timeout = 500 }: FetchMessagesOptions) {
        await waitFor(timeout);
        const lastIndex = this.messages.findIndex((message) => message.id === cursor);
        const messagesPage = this.messages.slice(lastIndex - pageSize, lastIndex);
        const hasMore = messagesPage[0] !== this.messages[0];
        const newCursor = hasMore ? messagesPage[0].id : null;
        return {
            data: messagesPage,
            cursor: newCursor,
        };
    }

    async sendNewMessage(message: ChatMessage) {
        await waitFor(300);
        this.messages.push(message);
        this.eventListeners['new-message'].forEach((callback) => callback({ message }));
    }

    notifyTypingUser(userId: number) {
        this.eventListeners['someone-typing'].forEach((callback) => callback({ userId }));
    }

    on<T extends MockChatProviderEvent>(eventName: T, callback: (payload: MockChatProviderEventPayload[T]) => void) {
        this.eventListeners[eventName].add(callback);
    }

    off<T extends MockChatProviderEvent>(eventName: T, callback: (payload: MockChatProviderEventPayload[T]) => void) {
        this.eventListeners[eventName].delete(callback);
    }
}

export const groupMessages = <T>(messages: T[], isFollowupMessage: (message: T, prevMessage?: T) => boolean) =>
    messages.reduce<T[][]>((groups, message, i, messages) => {
        if (isFollowupMessage(message, messages[i - 1])) {
            groups[groups.length - 1].push(message);
        } else {
            groups.push([message]);
        }
        return groups;
    }, []);
