import React, { useState } from 'react';
import ChatScrollArea from '../..';
import { useNewMessages } from './hooks/useNewMessages';
import { useMockChat } from './hooks/useMockChat';
import SimpleMessage from './SimpleMessage';

export default function Primary() {
  const chat = useMockChat({ numberOfAuthors: 2, numberOfMessages: 1 });
  const [messages, setMessages] = useState(chat.messages);
  useNewMessages(chat, setMessages);

  return (
    <ChatScrollArea>
      {messages.map((message) => (
        <SimpleMessage key={message.id} message={message} currentAuthor={chat.authors[0]} />
      ))}
    </ChatScrollArea>
  );
}

