import { useMemo } from 'react';
import { MockChatProvider } from '../../utils';

interface UseMockChatProps {
    numberOfMessages: number;
    withAgent?: boolean;
    numberOfAuthors?: number;
}

export function useMockChat({ withAgent, numberOfAuthors, numberOfMessages }: UseMockChatProps) {
    return useMemo(
        () => new MockChatProvider({ numberOfAuthors, numberOfMessages, withAgent }),
        [numberOfAuthors, numberOfMessages, withAgent]
    );
}
