import { useState, useRef } from 'react';
import throttle from 'lodash/throttle';
import clamp from 'lodash/clamp';
import { useLatest, useIsomorphicLayoutEffect } from '@fiverr-private/hooks';

interface UseRelativeScrollTopOptions {
    loadingThreshold: number;
    hasMore: boolean;
    onLoadMore?: () => Promise<any>;
}

const getIsCloseToBottom = ({
    scrollTop,
    scrollHeight,
    clientHeight,
}: {
    scrollTop: number;
    scrollHeight: number;
    clientHeight: number;
}) => scrollTop + clientHeight * 2 >= scrollHeight;

export const useChatScrolling = (
    ref: React.RefObject<HTMLDivElement>,
    { hasMore, loadingThreshold, onLoadMore }: UseRelativeScrollTopOptions
) => {
    const isLoadingMessagesRef = useRef(false);
    const scrollHeightRef = useRef(0);
    const isAtBottomRef = useRef(true);
    const [isCloseToBottom, setIsCloseToBottom] = useState(true);
    const contextRef = useLatest({
        onLoadMore,
        loadingThreshold,
        hasMore,
        isCloseToBottom,
    });
    const prevHasMoreRef = useRef(hasMore);

    const scrollToBottom = () => {
        ref.current?.scrollTo({ top: ref.current?.scrollHeight });
        isAtBottomRef.current = true;
    };

    useIsomorphicLayoutEffect(() => {
        const scrollableElement = ref.current;

        const mutationObserver = new MutationObserver(() => {
            if (ref.current) {
                const { scrollTop, scrollHeight: newScrollHeight, clientHeight } = ref.current;

                if (isAtBottomRef.current) {
                    ref.current.scrollTo({ top: ref.current?.scrollHeight });
                }

                if ((contextRef.current.hasMore || prevHasMoreRef.current) && scrollTop === 0) {
                    ref.current.scrollTo({ top: newScrollHeight - scrollHeightRef.current });
                }

                const isCloseToBottom = getIsCloseToBottom({ scrollTop, scrollHeight: newScrollHeight, clientHeight });
                if (isCloseToBottom !== contextRef.current.isCloseToBottom) {
                    setIsCloseToBottom(isCloseToBottom);
                }

                scrollHeightRef.current = newScrollHeight;
                prevHasMoreRef.current = contextRef.current.hasMore;
            }
        });

        const scrollListener = async () => {
            if (!ref.current) {
                return;
            }

            const context = contextRef.current;
            const { scrollTop, scrollHeight, clientHeight } = ref.current;

            scrollHeightRef.current = scrollHeight;
            const isCloseToBottom = getIsCloseToBottom({ scrollTop, scrollHeight, clientHeight });
            if (isCloseToBottom !== context.isCloseToBottom) {
                setIsCloseToBottom(isCloseToBottom);
            }
            isAtBottomRef.current = scrollHeight - clientHeight - scrollTop <= 1;

            const relativeScrollTop = clamp(scrollTop / clientHeight, 0, Infinity);
            if (
                !isLoadingMessagesRef.current &&
                context.onLoadMore &&
                context.hasMore &&
                (relativeScrollTop <= context.loadingThreshold || scrollHeight <= clientHeight)
            ) {
                isLoadingMessagesRef.current = true;
                try {
                    await context.onLoadMore();
                } finally {
                    isLoadingMessagesRef.current = false;
                }
            }
        };
        const throttledScrollListener = throttle(scrollListener, 1000 / 60);

        if (scrollableElement) {
            scrollableElement.addEventListener('scroll', throttledScrollListener);
            scrollableElement.scrollTo({ top: scrollableElement.scrollHeight });
            mutationObserver.observe(scrollableElement, {
                childList: true,
                subtree: true,
                characterData: true,
                attributes: true,
            });
        }

        return () => {
            mutationObserver.disconnect();
            scrollableElement?.removeEventListener('scroll', throttledScrollListener);
            throttledScrollListener.cancel();
        };
    }, []);

    return { isCloseToBottom, scrollToBottom };
};
